func newUser() unsafe.Pointer { return unsafe.Pointer(new(scim.User)) }

func newNUser(n int) unsafe.Pointer { return unsafe.Pointer(unsafe.SliceData(make([]scim.User, n))) }

func ptrUser(p unsafe.Pointer, c int32) any {
	r := (*scim.User)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.DirectoryID))
	case 4:
		return (*string)(unsafe.Pointer(&r.UserID))
	case 5:
		return &r.UserName
	case 6:
		return &r.ExternalID
	case 7:
		return &r.Active
	case 8:
		return &r.Provisioned
	case 9:
		return &r.RolesVersion
	case 10:
		return &r.RolesReconciledVersion
	case 11:
		return &r.CreatedAt
	case 12:
		return &r.UpdatedAt
	}
	return nil
}

func valueUser(p unsafe.Pointer, c int32) any {
	r := (*scim.User)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.DirectoryID)
	case 4:
		return string(r.UserID)
	case 5:
		return r.UserName
	case 6:
		if r.ExternalID == "" {
			return nil
		}
		return r.ExternalID
	case 7:
		return r.Active
	case 8:
		return r.Provisioned
	case 9:
		return r.RolesVersion
	case 10:
		return r.RolesReconciledVersion
	case 11:
		return r.CreatedAt
	case 12:
		return r.UpdatedAt
	}
	return nil
}

func attachUser(p unsafe.Pointer, rel int32, child unsafe.Pointer) {
	r := (*scim.User)(p)
	switch rel {
	case 0:
		r.User = (*tenant.User)(child)
	}
}

func init() {
	groupMembersTable.Relations[0].Target = tenantdb.UsersSchema()
	usersTable.Relations[0].Target = tenantdb.UsersSchema()
}
